python
import json
import logging
import os
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from pathlib import Path
from typing import Any

from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import FileResponse, JSONResponse, StreamingResponse
from openai import AsyncOpenAI
from starlette.middleware.cors import CORSMiddleware


logger = logging.getLogger("chat")
logging.basicConfig(level=logging.INFO)

BASE_DIR = Path(__file__).resolve().parent
INDEX_FILE = BASE_DIR / "index.html"
MANIFEST_FILE = BASE_DIR / "manifest.webmanifest"
SERVICE_WORKER_FILE = BASE_DIR / "sw.js"


def get_api_key() -> str:
    api_key = os.getenv("BLUESMINDS_API_KEY") or os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("BLUESMINDS_API_KEY vagy OPENAI_API_KEY nincs beállítva.")
    return api_key


def get_base_url() -> str | None:
    configured_base_url = os.getenv("BLUESMINDS_BASE_URL")
    if configured_base_url:
        return configured_base_url
    if os.getenv("BLUESMINDS_API_KEY"):
        return "https://api.bluesminds.com/v1"
    return None


def create_client() -> AsyncOpenAI:
    kwargs: dict[str, Any] = {"api_key": get_api_key()}
    base_url = get_base_url()
    if base_url:
        kwargs["base_url"] = base_url
    return AsyncOpenAI(**kwargs)


@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.openai_client = create_client()
    try:
        yield
    finally:
        await app.state.openai_client.close()


app = FastAPI(lifespan=lifespan)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["*"],
)


def get_client(request: Request) -> AsyncOpenAI:
    client = getattr(request.app.state, "openai_client", None)
    if not isinstance(client, AsyncOpenAI):
        raise RuntimeError("Az API kliens nem érhető el.")
    return client


def normalize_content(content: Any) -> Any:
    if isinstance(content, str):
        if not content.strip():
            raise ValueError("Az üzenet tartalma üres.")
        return content

    if isinstance(content, list):
        if not content:
            raise ValueError("Az üzenet tartalma üres.")

        normalized_parts: list[dict[str, Any]] = []
        for part in content:
            if not isinstance(part, dict):
                raise ValueError("Az üzenet content elemeinek objektumnak kell lenniük.")
            part_type = part.get("type")
            if not isinstance(part_type, str) or not part_type:
                raise ValueError("Az üzenet content elemének érvényes type mezővel kell rendelkeznie.")
            normalized_parts.append(part)

        return normalized_parts

    raise ValueError("Az üzenet content mezőjének szövegnek vagy content-listának kell lennie.")


def normalize_message(item: Any) -> dict[str, Any]:
    if not isinstance(item, dict):
        raise ValueError("Minden üzenetnek objektumnak kell lennie.")

    role = item.get("role")
    if role not in {"system", "developer", "user", "assistant", "tool", "function"}:
        raise ValueError("Az üzenet role mezője érvénytelen.")

    normalized: dict[str, Any] = {"role": role}

    if "content" in item and item["content"] is not None:
        normalized["content"] = normalize_content(item["content"])

    for key in ("name", "tool_call_id", "tool_calls", "function_call", "refusal", "audio"):
        if key in item:
            normalized[key] = item[key]

    if role in {"system", "developer", "user"} and "content" not in normalized:
        raise ValueError(f"A(z) {role} üzenethez kötelező a content mező.")

    if role == "assistant" and not any(
        key in normalized for key in ("content", "tool_calls", "function_call", "refusal", "audio")
    ):
        raise ValueError("Az assistant üzenetnek tartalmat vagy érvényes hívási adatot kell tartalmaznia.")

    if role == "tool":
        if not isinstance(normalized.get("tool_call_id"), str) or not normalized["tool_call_id"]:
            raise ValueError("A tool üzenethez kötelező az érvényes tool_call_id mező.")
        if "content" not in normalized:
            raise ValueError("A tool üzenethez kötelező a content mező.")

    if role == "function" and "content" not in normalized:
        raise ValueError("A function üzenethez kötelező a content mező.")

    return normalized


def make_messages(payload: dict[str, Any]) -> list[dict[str, Any]]:
    messages = payload.get("messages")
    if messages is not None:
        if not isinstance(messages, list) or not messages:
            raise ValueError("A messages mezőnek nem üres listának kell lennie.")
        return [normalize_message(item) for item in messages]

    for field_name in ("fullText", "rawText", "message"):
        value = payload.get(field_name)
        if isinstance(value, str) and value.strip():
            return [{"role": "user", "content": value}]

    raise ValueError("Az üzenet üres.")


def get_model(payload: dict[str, Any]) -> str:
    model = payload.get("model") or os.getenv("BLUESMINDS_MODEL", "claude-fable-5")
    if not isinstance(model, str) or not model.strip():
        raise ValueError("A model mezőnek nem üres szövegnek kell lennie.")
    return model


def build_completion_options(payload: dict[str, Any]) -> dict[str, Any]:
    allowed_keys = {
        "frequency_penalty",
        "logit_bias",
        "logprobs",
        "max_completion_tokens",
        "max_tokens",
        "n",
        "parallel_tool_calls",
        "presence_penalty",
        "response_format",
        "seed",
        "service_tier",
        "stop",
        "store",
        "temperature",
        "tool_choice",
        "tools",
        "top_logprobs",
        "top_p",
        "user",
    }
    return {key: payload[key] for key in allowed_keys if key in payload}


def sse(event: str, data: dict[str, Any]) -> str:
    return f"event: {event}\ndata: {json.dumps(data, ensure_ascii=False, separators=(',', ':'))}\n\n"


async def stream_completion(
    client: AsyncOpenAI,
    model: str,
    messages: list[dict[str, Any]],
    options: dict[str, Any],
) -> AsyncIterator[str]:
    try:
        stream = await client.chat.completions.create(
            model=model,
            messages=messages,
            stream=True,
            **options,
        )

        logger.info("chat_completion_stream_started model=%s message_count=%d", model, len(messages))

        completion_id: str | None = None
        finish_reason: str | None = None
        emitted_content = False

        async for chunk in stream:
            if completion_id is None:
                chunk_id = getattr(chunk, "id", None)
                if isinstance(chunk_id, str):
                    completion_id = chunk_id

            choices = getattr(chunk, "choices", None) or []
            for choice in choices:
                delta = getattr(choice, "delta", None)
                content = getattr(delta, "content", None) if delta else None
                if isinstance(content, str) and content:
                    emitted_content = True
                    yield sse("content", {"delta": content})

                choice_finish_reason = getattr(choice, "finish_reason", None)
                if isinstance(choice_finish_reason, str):
                    finish_reason = choice_finish_reason

        logger.info(
            "chat_completion_stream_finished model=%s response_id=%s emitted_content=%s finish_reason=%s",
            model,
            completion_id,
            emitted_content,
            finish_reason,
        )
        yield sse(
            "done",
            {
                "done": True,
                "id": completion_id,
                "finish_reason": finish_reason,
            },
        )
    except Exception as error:
        logger.exception("chat_completion_stream_error model=%s", model)
        yield sse(
            "error",
            {
                "message": "A modellválasz streamelése sikertelen.",
                "type": "provider_error",
            },
        )


@app.get("/")
async def index() -> FileResponse:
    if not INDEX_FILE.is_file():
        raise HTTPException(status_code=404, detail="Az index.html fájl nem található.")
    return FileResponse(INDEX_FILE, media_type="text/html")


@app.get("/manifest.webmanifest")
async def manifest() -> FileResponse:
    if not MANIFEST_FILE.is_file():
        raise HTTPException(status_code=404, detail="A manifest.webmanifest fájl nem található.")
    return FileResponse(MANIFEST_FILE, media_type="application/manifest+json")


@app.get("/sw.js")
async def service_worker() -> FileResponse:
    if not SERVICE_WORKER_FILE.is_file():
        raise HTTPException(status_code=404, detail="A sw.js fájl nem található.")
    return FileResponse(SERVICE_WORKER_FILE, media_type="application/javascript")


@app.get("/health")
async def health() -> JSONResponse:
    configured = bool(os.getenv("BLUESMINDS_API_KEY") or os.getenv("OPENAI_API_KEY"))
    return JSONResponse({"ok": True, "provider_configured": configured})


@app.post("/api/chat", response_model=None)
async def chat(request: Request) -> StreamingResponse | JSONResponse:
    try:
        payload = await request.json()
    except Exception:
        return JSONResponse({"message": "Érvénytelen JSON kérés."}, status_code=400)

    if not isinstance(payload, dict):
        return JSONResponse(
            {"message": "A kérés törzsének objektumnak kell lennie."},
            status_code=400,
        )

    try:
        get_api_key()
        messages = make_messages(payload)
        model = get_model(payload)
        options = build_completion_options(payload)
        client = get_client(request)
    except ValueError as error:
        return JSONResponse({"message": str(error)}, status_code=400)
    except RuntimeError as error:
        logger.exception("chat_configuration_error")
        return JSONResponse({"message": str(error)}, status_code=503)

    return StreamingResponse(
        stream_completion(client, model, messages, options),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


if __name__ == "__main__":
    import uvicorn

    port_value = os.getenv("PORT", "5000").strip()
    try:
        port = int(port_value)
    except ValueError as error:
